  --g-color-text-hint: #707a72;
  --g-color-line-generic: #dde3d9;
  --g-color-base-float: #ffffff;
  --g-text-accent-font-weight: 500;
  --g-text-display-4-font-size: clamp(44px, 5.5vw, 76px);
  --g-text-display-4-line-height: 1.12;
  --g-text-display-3-font-size: 54px;
  --g-text-display-3-line-height: 1.12;
  --g-text-display-2-font-size: 43px;
  --g-text-display-2-line-height: 1.15;
  --g-text-header-1-font-size: 21px;
  --g-text-header-1-line-height: 28px;
  --g-text-header-font-weight: 500;
}

*, *::before, *::after { box-sizing: border-box; }
body { margin: 0; min-width: 320px; }
button, a { -webkit-tap-highlight-color: transparent; }
.landing {
  max-width: 1240px;
  margin-inline: auto;
  padding: var(--g-spacing-10) var(--g-spacing-8) calc(var(--g-spacing-10) * 1.5);
  --pc-text-header-color: var(--g-color-text-primary);
}
.hero { padding-top: var(--g-spacing-2); }
.wordmark {
  margin: 0 0 calc(var(--g-spacing-10) * 1.4);
  font-size: 32px;
  font-weight: 700;
  letter-spacing: -1.8px;
  color: var(--g-color-text-primary);
}
.wordmark-dot { color: var(--g-color-text-brand); }
.hero-label {
  display: inline-block;
  padding: var(--g-spacing-2) var(--g-spacing-4);
  margin-bottom: var(--g-spacing-4);
  border: 1px solid var(--g-color-line-generic);
  border-radius: var(--g-border-radius-xl);
  background: var(--g-color-base-selection);
  color: var(--g-color-text-brand);
  font-size: 10px;
  font-weight: 600;
  line-height: 16px;
  letter-spacing: 1.5px;
}
.hero-accent { color: var(--g-color-text-brand); }
.hero-description {
  color: var(--g-color-text-secondary);
  font-size: 17px;
  line-height: 1.65;
  margin: var(--g-spacing-6) 0 0;
}
.hero-note {
  color: var(--g-color-text-hint);
  font-size: 12px;
  margin: var(--g-spacing-5) 0 0;
}
.benefits { margin-top: var(--g-spacing-10); }
.benefit {
  height: 100%;
  padding: var(--g-spacing-7);
  background: var(--g-color-base-float);
  border: 1px solid var(--g-color-line-generic);
  border-radius: var(--g-border-radius-l);
}
.benefit-number {
  display: block;
  color: var(--g-color-text-brand);
  font-variant-numeric: tabular-nums;
  letter-spacing: 2px;
  margin-bottom: var(--g-spacing-7);
}
.benefit-title { margin: 0 0 var(--g-spacing-3); letter-spacing: -.4px; }
.benefit-description { margin: 0; color: var(--g-color-text-secondary); line-height: 1.65; }
.cta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--g-spacing-8);
  margin: var(--g-spacing-8) var(--g-spacing-4) 0;
  padding: var(--g-spacing-9) var(--g-spacing-10);
  background: var(--g-color-base-selection);
  border: 1px solid var(--g-color-line-generic);
  border-radius: var(--g-border-radius-l);
}
.cta-copy { flex: 1; min-width: 0; }
.eyebrow { color: var(--g-color-text-brand); font-size: 9px; letter-spacing: 1.4px; margin: 0 0 var(--g-spacing-3); }
.cta h2 { margin: 0; font-weight: 500; letter-spacing: -.7px; }
.cta-description { color: var(--g-color-text-secondary); margin: var(--g-spacing-3) 0 0; }
.cta-action { flex-shrink: 0; text-align: center; }
.start-button {
  --g-button-border-radius: var(--g-border-radius-m);
  --g-button-text-color: var(--g-color-text-brand-contrast);
  --g-button-text-color-hover: var(--g-color-text-brand-contrast);
  min-width: 224px;
  font-weight: 500;
}
.button-arrow { margin-left: var(--g-spacing-6); font-size: 19px; }
.cta-note { color: var(--g-color-text-secondary); margin: var(--g-spacing-3) 0 0; font-size: 11px; }
.timer { font-variant-numeric: tabular-nums; }
.demo-note { display: block; margin-top: var(--g-spacing-1); color: var(--g-color-text-hint); }

@media (max-width: 900px) {
  .landing { padding-inline: var(--g-spacing-4); }
  .benefit { padding: var(--g-spacing-5); }
  .cta { padding: var(--g-spacing-7); gap: var(--g-spacing-6); }
  .cta h2 { --g-text-display-1-font-size: 25px; }
}
@media (max-width: 768px) {
  .landing { padding-top: var(--g-spacing-6); }
  .wordmark { margin-bottom: var(--g-spacing-9); }
  .benefits { margin-top: var(--g-spacing-6); }
  .benefit-number { margin-bottom: var(--g-spacing-4); }
  .cta { flex-direction: column; text-align: center; align-items: stretch; }
  .hero-description { font-size: 16px; }
}
@media (max-width: 400px) {
  .landing { padding-inline: var(--g-spacing-2); }
  .hero-label { font-size: 9px; letter-spacing: 1px; }
  .hero-description br { display: none; }
  .cta { padding-inline: var(--g-spacing-5); }
  .eyebrow { letter-spacing: 1px; }
}
EOF"
